using Tempo.Blazor.NotionEditor.Models;
using Tempo.Blazor.NotionEditor.Enums;

var block = new PageBlock
{
    Id            = Guid.NewGuid(),
    PageId        = pageId,
    ParentBlockId = null,
    Type          = BlockType.Paragraph,
    Order         = 0,
    Content       = new TextBlockContent { Html = "Hello <strong>world</strong>" },
    CreatedAt     = DateTime.UtcNow,
    LastEditedAt  = DateTime.UtcNow
};

if (block.Type == BlockType.Image && block.Content is ImageBlockContent img)
{
    Console.WriteLine(img.Url);
}
else if (block.Type is BlockType.Heading1 or BlockType.Heading2 or BlockType.Heading3
         && block.Content is HeadingBlockContent h)
{
    Console.WriteLine($"H{h.Level}: {h.Html}");
}
